int insideCount = 0;
std::mt19937 gen(42);
std::uniform_real_distribution<double> dist(-1.0, 1.0);

for (int i = 0; i < numberOfChecks; ++i) {
    // Generate a random direction vector
    double dx = dist(gen);
    double dy = dist(gen);
    double dz = dist(gen);

    // Normalize the direction vector
    double length = std::sqrt(dx * dx + dy * dy + dz * dz);
    if (length < 1e-9) {
        i--; // Retry if vector is too short
        continue;
    }

    CGAL::Vector_3<double> direction(dx / length, dy / length, dz / length);

    // Use CGAL AABB tree to count intersections along the ray
    // The ray is defined by point p and direction
    int intersections = tree.count_intersections(p, direction);

    // For a closed mesh, an odd number of intersections means the point is inside
    if (intersections % 2 != 0) {
        insideCount++;
    }
}

// Return true if the majority of random rays indicate the point is inside
return insideCount > (numberOfChecks / 2);
// END_CODE

